  (1, null, '30-45 ml (2-3 c. à soupe) de fécule de maïs ou de fécule de tapioca (la quantité requise dépendra du degré d’humidité du tofu)', 30, 45, 'ml', 'fécule de maïs ou de fécule de tapioca', '2-3 c. à soupe; la quantité requise dépendra du degré d’humidité du tofu', false, 'Fécule de maïs'),
  (2, null, '80 ml (1/3 tasse) de végénaise (mayonnaise végétalienne) du commerce', 80, null, 'ml', 'végénaise du commerce', '1/3 tasse; mayonnaise végétalienne', false, 'Mayonnaise végétalienne (Vegenaise)'),
