  (4, null, '15 ml (1 c. à soupe) de sauce soya ou tamari', 15, null, 'ml', 'sauce soya ou tamari', '1 c. à soupe', false, 'Sauce soya'),
  (5, null, '15 ml (1 c. à soupe) de jus de citron ou de vinaigre neutre', 15, null, 'ml', 'jus de citron ou de vinaigre neutre', '1 c. à soupe', false, 'Citron'),
