  (9, null, '90 ml (1/4 tasse + 2 c. à soupe) de levure alimentaire en flocons', 90, null, 'ml', 'levure alimentaire en flocons', '1/4 tasse + 2 c. à soupe', false, 'Levure alimentaire'),
  (10, null, '2,5 ml (1/2 c. à thé) de poudre d’ail', 2.5, null, 'ml', 'poudre d’ail', '1/2 c. à thé', false, 'Poudre d''ail'),
  (11, null, '15 ml (1 c. à soupe) d’huile végétale ou huile végétale en vaporisateur (facultatif)', 15, null, 'ml', 'huile végétale ou huile végétale en vaporisateur', '1 c. à soupe', true, 'Huile végétale'),
  (12, null, '1 oignon vert haché pour décorer (facultatif)', 1, null, null, 'oignon vert haché pour décorer', null, true, 'Oignon vert'),
  (13, null, 'Légumes pour accompagner le tofu (au choix)', null, null, null, 'Légumes pour accompagner le tofu', 'au choix', false, 'Légumes d''accompagnement (au choix)')
) v(position, section, raw, quantity, quantity_max, unit, name, note, optional, catalog)
left join ingredients i on i.household_id is null and i.name = v.catalog where r.title = 'Tofu Magique Bang Bang';
update recipes set instructions = '["Préchauffer le four à 375°. Couvrir une plaque de papier parchemin ou d’un tapis de cuisson anti-adhésif.","Préparation du tofu","Avec les doigts, défaire le tofu épongé en morceaux de la grosseur d’une bouchée. Ajouter la fécule de maïs et brasser doucement avec les mains pour bien enrober chaque morceau. Réserver.","Préparation de la sauce","Dans un petit bol, mettre la végénaise, la pâte de chili Sambal Oelek, la sauce soya, le jus de citron et le sirop d’érable. Mélanger jusqu’à l’obtention d’une texture homogène.","Préparation de l’appareil liquide","Prélever 3 c. à soupe de la sauce et la transférer dans un autre bol. Ajouter 3 c. à soupe d’eau, et mélanger jusqu’à l’obtention d’une texture homogène. Cette sauce diluée servira d’appareil liquide pour faire adhérer la chapelure.Pendant ce temps, mettre le restant de sauce à base de végénaise au réfrigérateur.","Préparation de la chapelure","Dans un bol, mettre la chapelure panko, la levure alimentaire et la poudre d’ail. Mélanger.","Assemblage","Préparer une station de travail avec le bol de sauce diluée et celui de mélange de chapelure.En procédant un morceau à la fois, tremper les morceaux de tofu dans la sauce diluée, et ensuite dans la préparation de chapelure. Disposer sur la plaque.Si on le souhaite, on peut ajouter un filet d’huile ou utiliser un vaporisateur d’huile sur les morceaux de tofu panés (facultatif, mais donnera un tofu plus croustillant!).","Cuisson","Enfourner 30 à 35 minutes, ou jusqu’à ce que les morceaux soient bien dorés (il est possible de les tourner à mi-cuisson, mais ce n’est pas nécessaire).","Présentation","Sortir la sauce du réfrigérateur.Servir avec la sauce en garniture ou en trempette. Décorer avec des oignons verts hachés.Avec un accompagnement de légumes verts (ici, j’ai fait cuire à la poêle des moitiés de bok choy avec un peu de sauce soya et de sirop d’érable, tout simplement!), on a un repas!","","","","","",""]'::jsonb, source_url = coalesce(source_url, 'https://www.loouniecuisine.com/fr/recettes/plats-principaux/tofu-magique-bang-bang/') where title = 'Tofu Magique Bang Bang';
