left join ingredients i on i.household_id is null and i.name = v.catalog where r.title = 'Ramen crémeux à la courge avec tempeh au sésame, de Loounie';
update recipes set instructions = '["Dans une cocotte ou un grand chaudron, chauffer l’huile à feu moyen-élevé. Ajouter l’oignon, les champignons séchés et le sel, puis faire sauter durant 3 min ou jusqu’à ce que l’oignon soit légèrement translucide.","Ajouter la courge et faire sauter durant 5 min.","Ajouter l’ail, le gingembre, la sauce soya, le vinaigre de riz, la pâte de piment et la cassonade. Bien mélanger et cuire durant 2 min.","Ajouter le bouillon, bien mélanger et porter à ébullition. Baisser ensuite le feu à doux-modéré, couvrir et laisser mijoter durant 10-12 min ou jusqu’à ce que la courge soit bien tendre. Ajouter la boisson de soya, mélanger et retirer du feu.","À l’aide d’un mélangeur, broyer jusqu’à l’obtention d’une texture lisse. Réserver au chaud.","Avec les doigts, défaire le tempeh en morceaux de la grosseur d’une petite bouchée et mettre dans un bol. Ajouter la fécule de maïs, le sel, et bien mélanger.","Dans une poêle antiadhésive, à feu moyen-élevé, chauffer l’huile. Ajouter le tempeh et faire sauter durant 5 min en brassant régulièrement, jusqu’à ce que les petits morceaux de tempeh soient bien colorés.","Dans un petit bol, mettre la sauce soya, la cassonade, l’huile de sésame grillé et le vinaigre de riz, puis mélanger jusqu’à ce que la cassonade soit bien dissoute.","Verser la sauce sur le tempeh et mélanger afin de bien enrober tous les morceaux. Ajouter les graines de sésame grillées, bien mélanger et réserver au chaud.","Dans la même poêle utilisée pour le tempeh, chauffer l’huile de canola à feu moyen-élevé. Ajouter les quartiers de chou et faire griller durant 5-6 min ou jusqu’à ce qu’ils soient bien colorés d’un côté. Ajouter 30 ml (2 c. à soupe) d’eau pour terminer la cuisson à la vapeur, sans retourner les quartiers de chou. Une fois l’eau évaporée, retirer le chou de la poêle et réserver au chaud.","Dans la même poêle, faire sauter les tomates cerises durant 2-3 min ou jusqu’à ce qu’elles soient bien colorées. Réserver.","Répartir les nouilles cuites dans les bols et y verser le bouillon. Ajouter le tempeh, le chou, les tomates et les champignons enokis, si désiré. Garnir avec l’oignon vert et du chili croquant ou de l’huile piquante, si désiré."]'::jsonb, source_url = coalesce(source_url, 'https://veroniquecloutier.com/cuisine/recette-vegane-soupe-ramen-cremeux-a-la-courge-avec-tempeh-au-sesame-de-loounie') where title = 'Ramen crémeux à la courge avec tempeh au sésame, de Loounie';
