update recipes set instructions = '["Pelez la courge et coupez-la en cubes. Tranchez grossièrement l’oignon et le céleri.","Dans une grande casserole, déposez tous les ingrédients. Poivrez généreusement et ajoutez une pincée de sel.","Portez à ébullition à feu vif. Réduisez à feu moyen et laissez mijoter 20 minutes.","Au mélangeur électrique (blender) ou au pied-mélangeur, réduisez la soupe en purée lisse.","Répartissez le potage dans 6 bols, garnissez de croûtons (voir NOTE) et servez."]'::jsonb, source_url = coalesce(source_url, 'https://ici.radio-canada.ca/mordu/recettes/356/potage-courge-musquee') where title = 'Potage à la courge musquée';
