update recipes set instructions = '["Cook the couscous according to the package instructions, then drain.","Meanwhile, drizzle oil in a medium pan over medium-high heat. When hot, add the chickpeas, tomatoes, salt, and pepper. Cook for 5 to 7 minutes, stirring occasionally. Remove from the heat.","In a small bowl, mix together the ingredients for the dressing.","To a large bowl, add the drained couscous, tomato and chickpea mixture, cucumber slices, olives, and fresh herbs. Add the dressing, toss to combine, spinkle over the almonds, and enjoy!"]'::jsonb, source_url = coalesce(source_url, 'https://www.pickuplimes.com/recipe/warm-pearl-couscous-salad-542') where title = 'Warm Pearl Couscous Salad';
