update recipes set instructions = '["Dans un bol, mélanger tous les ingrédients de la salade de haricots noirs.","Dans une assiette creuse, écraser les avocats jusqu’à l’obtention d’une texture semi-lisse. Ajouter la lime et le sel et bien mélanger.","Déposer une moitié de patate douce dans une assiette. Étendre un peu de guacamole sur le dessus, ajouter de la salade de haricots et les garnitures, si désiré. Répéter pour toutes les moitiés de patates douces."]'::jsonb, source_url = coalesce(source_url, 'https://margauxfood.ca/recette/patates-douces-farcies-a-la-mexicaine/') where title = 'Patates douces farcies à la mexicaine';
