) v(position, section, raw, quantity, quantity_max, unit, name, note, optional, catalog)
left join ingredients i on i.household_id is null and i.name = v.catalog where r.title = 'Lasagne au pesto, petits pois et courgette';
update recipes set instructions = '["Faire tremper les 4 tasses de basilic dans un bol d’eau glacée pendant 5 minutes. Égoutter et bien presser pour retirer un maximum d’eau.","Dans un blender ou robot culinaire, mixer le basilic avec ½ tasse d’huile d’olive, ¼ tasse de noix, ¼ tasse de parmesan, le jus et zeste de ½ citron, 2 gousses d’ail et ½ c. à thé de sel jusqu’à l’obtention d’un pesto lisse. Ajouter un peu d’huile au besoin pour ajuster la texture. Réserver.","Dans une grande poêle à feu moyen, chauffer 1 c. à soupe d’huile d’olive. Ajouter les 2 poireaux tranchés et la courgette en dés. Cuire environ 2 à 3 minutes. Incorporer 1 à 2 gousses d’ail et 1 tasse de petits pois surgelés. Saler et poivrer, puis poursuivre la cuisson 2 minutes, jusqu’à ce que les légumes soient tendres mais encore légèrement croquants. Réserver.","Dans une casserole, faire fondre ½ tasse de beurre à feu moyen. Ajouter ½ tasse de farine et cuire 1 à 2 minutes en remuant. Verser graduellement 3 tasses de lait, en fouettant constamment pour éviter les grumeaux.","Ajouter une pincée de muscade, saler et poivrer. Cuire quelques minutes jusqu’à épaississement. Réserver.","Préchauffer le four à 375 °F et placer la grille au milieu.","Beurrer un moule rectangulaire de 9 x 13 pouces.","Déchirer la mozzarella fraîche (250 g) en morceaux et bien l’éponger pour retirer l’excès d’eau.","Au total, prévoir 5 étages. Si vous utilisez des pâtes à lasagne fraîches, prévoir 2 pâtes + retailles d''environ 1 pouce pour couvrir chaque étage de façon uniforme. Si vous utilisez des pâtes sèches cuites, prévoir 3 pâtes par étage. Étaler 1 à 2 c. à soupe de béchamel au fond du plat.","1er étage = Pâtes + béchamel + pesto + parmesan","2e étage = Pâtes + béchamel + pesto + la moitié des légumes + parmesan","3e étage = Pâtes + béchamel + pesto + parmesan","4e étage = Pâtes + béchamel + pesto + le reste des légumes + parmesan","Dernier étage = Pâtes + béchamel + pesto + mozzarella défaite, bien répartie + parmesan","Couvrir de papier d’aluminium et cuire 20 minutes.","Retirer le papier et poursuivre la cuisson 20 à 25 minutes, jusqu’à ce que le dessus soit bien doré.","Laisser reposer 5-10 minutes avant de servir."]'::jsonb, source_url = coalesce(source_url, 'https://dashofhoney.ca/fr/lasagne-au-pesto-petits-pois-et-courgette/') where title = 'Lasagne au pesto, petits pois et courgette';
