update recipes set instructions = '["Cook the rice according to the package instructions. Then spread it out on a large tray and let it cool off.","Add oil to a large pan and heat over medium-high.","Press rice into a flat layer on the pan and cook for about 15 - 20 minutes, or until golden and crispy to your liking. Toss once or twice while cooking.","Meanwhile, mix the dressing ingredients together in a small bowl. Set aside.","Add the beans and parsley to a large bowl.","Break the rice into bite-sized clumps and add them to the bowl. When ready to enjoy, pour over the dressing and toss to coat. Enjoy!"]'::jsonb where title = 'Bean Crispy Salad';
