update recipes set instructions = '["Faire chauffer 1 c. à soupe d''huile d''olive dans un grand chaudron à feu moyen. Cuire les cubes de halloumi 2 minutes de chaque côté sans les toucher lors de la cuisson, ou jusqu''à ce qu''ils soient dorés. Réserver dans une assiette.","Ajouter 1 c. à soupe d''huile d''olive au chaudron et faire revenir l''oignon 5-6 minutes. Assaisonner.","Ajouter 4 c. à soupe de pâte de cari rouge et le gingembre frais râpé (1 morceau de 1 pouce de gingembre). Faire revenir 1 minute. Ajouter ensuite la patate douce en cubes et mélanger.","Verser 4 tasses de bouillon de légumes, ¾ de tasse de lentilles brunes sèches, 1 c. à soupe de sauce soya, 1 c. à soupe de sauce poisson et 1 c. à soupe de miel.","Porter à ébullition, réduire à feu doux et laisser mijoter 15-20 minutes ou jusqu''à ce que les lentilles et patates douces soient cuites.","Ajouter la canne de lait de coconut, 2-3 poignées de kale tranché et le fromage halloumi cuit. Faire revenir 1-2 minutes. Rectifier l''assaisonnement au besoin.","Servir sur du riz et garnir de coriandre fraîche."]'::jsonb, source_url = coalesce(source_url, 'https://dashofhoney.ca/fr/cari-patates-douces-lentilles-et-halloumi/') where title = 'Cari de patates douces, lentilles et halloumi';
