update recipes set instructions = '["Heat the oil in a large pan over medium-high heat. Cook the onions until golden, about 4 - 5 minutes.","Add the garlic and sauté for another 2 minutes.","Add the mushrooms and all the spices to the pan and cook for about 8 minutes. Add a small splash of water if needed to prevent the spices from burning, but note the mushrooms will also start to release their own liquid after a minute.","Add the lentils and chipotle sauce, stir and cook until everything is heated through.","Prepare the avocado cream by adding all the ingredients to a small food processor and blending on high until smooth. Alternatively, mash the ingredients in a bowl for a chunkier sauce.","Serve the mushroom lentil filling on the wraps and top with cabbage, juicy tomatoes, and crisp radish. Dollop on the avocado cream and serve with lime wedges. Enjoy!"]'::jsonb, source_url = coalesce(source_url, 'https://www.pickuplimes.com/recipe/mushroom-lentil-tacos-with-a-creamy-avocado-sauce-257') where title = 'Mushroom & Lentil Tacos with Garlic Avocado Cream';
