update recipes set instructions = '["Dans un grand chaudron à feu moyen, faire revenir l''oignon et l''huile d''olive pour 5 minutes. Assaisonner.","Ajouter l''ail et la pâte de tomate. Bien mélanger.","Ajouter la sauce tomate, l''eau, les tomates séchées, le vinaigre de cidre de pomme, le miel et les haricots blancs. Bien mélanger et assaisonner. Porter à ébullition et réduire à feu doux. Cuire pendant 10 minutes.","Dans une poêle à griller ou BBQ, cuire le fromage halloumi environ 3 minutes de chaque côté.","Après 10 minutes de cuisson, ajouter les épinards aux haricots et mélanger. Assaisonner au goût et ajouter de l''eau au besoin en fonction de la consistance.","Servir les haricots sauce tomate dans chaque assiette et garnir du fromage halloumi."]'::jsonb, source_url = coalesce(source_url, 'https://dashofhoney.ca/en/white-beans-in-tomato-sauce-with-grilled-halloumi/') where title = 'Haricots blancs sauce tomate & halloumi grillé';
