update recipes set instructions = '["Dans un grand chaudron à feu moyen, faire revenir l''oignon dans l''huile de coco ou le beurre.","Ajouter ensuite le gingembre, l''ail et la pâte de cari rouge. Cuire pour environ 1 minute.","Ajouter ensuite le lait de coco et bien mélanger. Ajouter la citrouille en cubes, le miel, la sauce soya et le jus de lime. Porter à ébullition et réduire le feu.","Laisser mijoter pour environ 10-12 minutes, jusqu''à ce que la citrouille soit tendre mais pas trop cuite.","Ajouter ensuite les pois chiches et les épinards. Cuire pour 1-2 minutes.","Ajuster l''assaisonnement et servir avec du riz ou des nouilles de riz. Garnir avec des arachides et de la coriandre."]'::jsonb, source_url = coalesce(source_url, 'https://dashofhoney.ca/en/creamy-pumpkin-thai-red-curry-coconut-milk/') where title = 'Cari rouge à la citrouille, pois chiches et épinards';
